mapper.insert:
INSERT INTO T_STOCK_PRICE
( STOCK_ID
,TRADE_DATE
,OPEN_PRICE
,HIGH_PRICE
,LOW_PRICE
,CLOSE_PRICE
,VOLUME
) VALUES (
#{stockId}
,#{tradeDate}
,#{openPrice}
,#{highPrice}
,#{lowPrice}
,#{closePrice}
,#{volume}
)
ON CONFLICT (STOCK_ID, TRADE_DATE) DO UPDATE
SET  OPEN_PRICE  = EXCLUDED.OPEN_PRICE
,HIGH_PRICE  = EXCLUDED.HIGH_PRICE
,LOW_PRICE   = EXCLUDED.LOW_PRICE
,CLOSE_PRICE = EXCLUDED.CLOSE_PRICE
,VOLUME      = EXCLUDED.VOLUME
,UPT_DAY     = NOW()

INSERT INTO T_STOCK_PRICE
( STOCK_ID
,TRADE_DATE
,OPEN_PRICE
,HIGH_PRICE
,LOW_PRICE
,CLOSE_PRICE
,VOLUME
) VALUES

( #{p.stockId}
,#{p.tradeDate}
,#{p.openPrice}
,#{p.highPrice}
,#{p.lowPrice}
,#{p.closePrice}
,#{p.volume}
)

ON CONFLICT (STOCK_ID, TRADE_DATE) DO UPDATE
SET  OPEN_PRICE  = EXCLUDED.OPEN_PRICE
,HIGH_PRICE  = EXCLUDED.HIGH_PRICE
,LOW_PRICE   = EXCLUDED.LOW_PRICE
,CLOSE_PRICE = EXCLUDED.CLOSE_PRICE
,VOLUME      = EXCLUDED.VOLUME
,UPT_DAY     = NOW()

INSERT INTO T_STOCK (
       SYMBOL
      ,NAME
      ,MARKET
      ,SECURITY_TYPE
      ,USE_YN
) VALUES

(      #{s.symbol}
      ,#{s.name}
      ,#{s.market}
      ,#{s.securityType}
      ,'Y'
)

ON CONFLICT (SYMBOL) DO UPDATE
   SET NAME          = EXCLUDED.NAME
      ,MARKET        = EXCLUDED.MARKET
      ,SECURITY_TYPE = EXCLUDED.SECURITY_TYPE
      ,UPT_DAY       = NOW()

mapper.update:
UPDATE T_STOCK S SET SHARES_OUTSTANDING = V.SHARES FROM (VALUES
(#{s.stockId}::BIGINT, #{s.sharesOutstanding}::BIGINT)
) AS V(ID, SHARES) WHERE 1=1 AND S.ID = V.ID

UPDATE T_STOCK S SET LAST_CLOSE = V.PRICE ,LAST_TRADE_DATE = V.TRADE_DATE FROM (VALUES
(#{s.stockId}::BIGINT, #{s.closePrice}::NUMERIC, #{s.tradeDate}::DATE)
) AS V(ID, PRICE, TRADE_DATE) WHERE 1=1 AND S.ID = V.ID AND S.LAST_CLOSE IS NULL

